<template><div class="rewards-console"><div class="heading"><div><h1>积分与活动</h1><p>免费积分、活动勋章与实物兑换，独立管理奖池和履约。</p></div><el-button :loading="loading" @click="load">刷新</el-button></div><el-alert title="积分只能免费发放，不支持购买、转让、提现或资金兑换；成长值独立保存。抽奖开关未确认前保持关闭。" type="info" :closable="false" /><el-tabs v-model="tab" @tab-change="changeTab"><el-tab-pane v-if="canRead" label="积分商品" name="goods" /><el-tab-pane v-if="canRead" label="抽奖活动" name="activities" /><el-tab-pane v-if="canGrant" label="免费积分发放" name="points" /><el-tab-pane v-if="canFulfill" label="兑换发货" name="orders" /></el-tabs><el-alert v-if="error" :title="error" type="error" :closable="false" class="gap" /><template v-if="tab==='points'"><el-form label-width="110px" class="grant-form" @submit.prevent="grant"><el-form-item label="玩家 ID"><el-input-number v-model="grantForm.memberId" :min="1" :precision="0" /><el-button @click="inspectPoints">查看余额与明细</el-button></el-form-item><el-form-item label="发放积分"><el-input-number v-model="grantForm.amount" :min="1" :max="1000000" :precision="0" /></el-form-item><el-form-item label="免费发放原因"><el-input v-model="grantForm.note" maxlength="200" placeholder="例如：免费社区活动参与奖励，不得用于付费购积分" /></el-form-item><el-form-item><el-button type="primary" :loading="saving" @click="grant">确认免费发放</el-button></el-form-item></el-form><p v-if="points">当前可用积分：<b>{{points.balance}}</b></p><el-table :data="points?.items||[]"><el-table-column prop="note" label="原因" /><el-table-column prop="delta" label="变动" /><el-table-column prop="balance" label="余额" /><el-table-column prop="createdAt" label="时间" /></el-table></template><template v-else><div class="toolbar"><el-button v-if="canManage&&['goods','activities'].includes(tab)" type="primary" @click="edit()">{{tab==='goods'?'添加积分商品':'添加抽奖活动'}}</el-button><el-select v-if="tab==='orders'" v-model="state" clearable placeholder="全部状态" @change="page=1;load()" style="width:160px"><el-option v-for="(label,value) in states" :key="value" :label="label" :value="value" /></el-select><span v-if="tab==='activities'" :class="drawEnabled?'live':'muted'">抽奖 {{drawEnabled?'已开启':'未开启'}}</span></div><el-table :data="rows" v-loading="loading" empty-text="暂无记录"><el-table-column prop="id" label="ID" width="70" /><el-table-column prop="title" label="名称" min-width="160" /><el-table-column v-if="tab!=='orders'" :prop="tab==='goods'?'image':'cover'" label="图片" width="100"><template #default="s"><el-image v-if="rewardImage(tab==='goods'?s.row.image:s.row.cover)" :src="rewardImage(tab==='goods'?s.row.image:s.row.cover)" style="width:68px;height:44px" fit="cover" /></template></el-table-column><el-table-column v-if="tab==='goods'" label="类型"><template #default="s">{{s.row.kind==='BADGE'?'活动勋章':'实物'}}</template></el-table-column><el-table-column v-if="tab!=='orders'" prop="pointsCost" label="积分消耗" /><el-table-column v-if="tab==='goods'" prop="stock" label="剩余库存" /><el-table-column v-if="tab==='orders'" prop="memberId" label="玩家 ID" /><el-table-column label="状态"><template #default="s">{{states[s.row.status]||{DRAFT:'草稿',ACTIVE:'上架中'}[s.row.status]}}</template></el-table-column><el-table-column label="操作" width="150"><template #default="s"><el-button v-if="tab==='orders'" link type="primary" @click="fulfill(s.row)">查看 / 发货</el-button><el-button v-else-if="canManage" link type="primary" @click="edit(s.row)">编辑</el-button><el-button v-if="tab==='activities'" link @click="copyLink(s.row.id)">复制页面路径</el-button></template></el-table-column></el-table><el-pagination v-if="tab!=='activities'" v-model:current-page="page" :total="total" :page-size="20" layout="total,prev,pager,next" @current-change="load" /></template>
<el-dialog v-model="dialog" :title="(form.id?'编辑':'添加')+(editorType==='goods'?'积分商品':'抽奖活动')" width="640px" :close-on-click-modal="false"><el-form label-width="100px"><el-form-item label="名称"><el-input v-model="form.title" maxlength="60" /></el-form-item><el-form-item v-if="editorType==='goods'" label="商品类型"><el-select v-model="form.kind" :disabled="!!form.id"><el-option label="活动勋章" value="BADGE" /><el-option label="实物商品" value="PHYSICAL" /></el-select></el-form-item><el-form-item v-if="editorType==='goods'&&form.kind==='BADGE'" label="勋章代码"><el-input v-model="form.badgeCode" :disabled="!!form.id" placeholder="大写字母 / 数字 / 下划线，创建后固定" maxlength="32" /></el-form-item><el-form-item :label="editorType==='goods'?'商品图片':'封面大图'"><el-upload :show-file-list="false" accept="image/png,image/jpeg" :before-upload="beforeUpload" :http-request="upload"><el-button :loading="uploading">上传公开图片</el-button></el-upload><el-image v-if="rewardImage(form.image||form.cover)" :src="rewardImage(form.image||form.cover)" fit="cover" style="width:160px;height:85px;margin-left:12px" /><span class="muted">上传后公开展示，请勿上传个人证件。</span></el-form-item><el-form-item label="说明"><el-input v-model="form.description" type="textarea" :rows="3" maxlength="1000" /></el-form-item><el-form-item :label="editorType==='goods'?'兑换积分':'单抽积分'"><el-input-number v-model="form.pointsCost" :min="1" :max="1000000" :precision="0" /><span v-if="editorType==='activities'">五连 = {{form.pointsCost*5}} 积分</span></el-form-item><el-form-item v-if="editorType==='goods'" label="当前库存"><el-input-number v-model="form.stock" :min="0" :max="1000000" :precision="0" /></el-form-item><template v-if="editorType==='activities'"><el-form-item label="开始时间"><el-date-picker v-model="form.startsAt" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss" /></el-form-item><el-form-item label="结束时间"><el-date-picker v-model="form.endsAt" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss" /></el-form-item><el-form-item label="奖池配置"><div><div class="prize-editor" v-for="(p,i) in form.prizes" :key="i"><el-select v-model="p.goodsId" placeholder="选择奖品" style="width:215px"><el-option label="下次好运（不中奖）" :value="0" /><el-option v-for="g in catalog" :key="g.id" :value="g.id" :label="g.title+' · 库存 '+g.stock" /></el-select><el-input-number v-model="p.weight" :min="1" :max="1000000" :precision="0" /><el-button link @click="form.prizes.splice(i,1)">移除</el-button></div><el-button :disabled="form.prizes.length>=8" @click="form.prizes.push({goodsId:0,weight:1})">添加格子</el-button><p class="muted">权重决定概率；售罄、下架、已拥有勋章退出奖池。五连每次更新可领取奖池，全部无法领取时整单回滚。</p></div></el-form-item></template><el-form-item label="状态"><el-radio-group v-model="form.status"><el-radio value="DRAFT">草稿</el-radio><el-radio value="ACTIVE">上架</el-radio></el-radio-group></el-form-item></el-form><template #footer><el-button :disabled="saving" @click="dialog=false">取消</el-button><el-button type="primary" :loading="saving" :disabled="uploading" @click="save">保存</el-button></template></el-dialog>
<el-dialog v-model="shippingDialog" title="兑换履约" width="550px"><template v-if="selected"><el-descriptions :column="1" border><el-descriptions-item label="商品">{{selected.title}}</el-descriptions-item><el-descriptions-item label="状态">{{states[selected.status]}}</el-descriptions-item><el-descriptions-item label="收货人">{{selected.recipient||'尚未填写'}}</el-descriptions-item><el-descriptions-item label="手机号">{{selected.phone||'—'}}</el-descriptions-item><el-descriptions-item label="地址">{{selected.address||'—'}}</el-descriptions-item></el-descriptions><el-form label-width="90px" class="gap"><el-form-item label="物流公司"><el-input v-model="shipping.carrier" :disabled="selected.status!=='WAIT_SHIP'" /></el-form-item><el-form-item label="物流单号"><el-input v-model="shipping.trackingNo" :disabled="selected.status!=='WAIT_SHIP'" /></el-form-item></el-form><el-button v-if="selected.status==='WAIT_SHIP'" type="primary" :loading="saving" @click="ship">确认发货</el-button></template></el-dialog>
</div></template>
<script setup>
import {ref,reactive,onMounted,onBeforeUnmount,watch} from 'vue';import {ElMessage,ElMessageBox} from 'element-plus';import useUserStore from '@/store/modules/user';import auth from '@/plugins/auth';import {getToken} from '@/utils/auth';import {rewardList,rewardDetail,saveReward,grantPoints,readPoints,shipReward,uploadReward,rewardImage} from '@/api/rewards'
const userStore=useUserStore();const canRead=auth.hasPermi('boost:rewards:read'),canManage=auth.hasPermi('boost:rewards:manage'),canGrant=auth.hasPermi('boost:rewards:grant'),canFulfill=auth.hasPermi('boost:rewards:fulfill')
const tab=ref(canRead?'goods':canGrant?'points':'orders'),rows=ref([]),page=ref(1),total=ref(0),state=ref(''),loading=ref(false),error=ref(''),saving=ref(false),dialog=ref(false),editorType=ref('goods'),form=reactive({}),catalog=ref([]),uploading=ref(false),drawEnabled=ref(false),points=ref(null),grantForm=reactive({memberId:1,amount:100,note:''}),shippingDialog=ref(false),selected=ref(null),shipping=reactive({carrier:'',trackingNo:''});const states={WAIT_ADDRESS:'待填写地址',WAIT_SHIP:'待发货',SHIPPED:'已发货',COMPLETED:'已完成'};let version=0,editVersion=0,grantIntent=null
function grantStorage(){return 'boost_reward_grant_pending_'+userStore.id}
function restoreGrant(){grantIntent=null;if(!userStore.id||!userStore.token)return;try{const value=JSON.parse(localStorage.getItem(grantStorage())||'null');if(value&&value.adminId===Number(userStore.id)&&typeof value.data?.requestKey==='string'){grantIntent=value;Object.assign(grantForm,JSON.parse(value.snapshot))}}catch{localStorage.removeItem(grantStorage())}}
let mutationVersion=0
function resetPrivate(){version++;editVersion++;mutationVersion++;rows.value=[];points.value=null;selected.value=null;shippingDialog.value=false;dialog.value=false;Object.assign(shipping,{carrier:'',trackingNo:''});error.value='';loading.value=false;saving.value=false;restoreGrant()}
onMounted(()=>{restoreGrant();load()});onBeforeUnmount(resetPrivate);watch(()=>[userStore.id,userStore.token],resetPrivate,{flush:'sync'})
function changeTab(){version++;editVersion++;rows.value=[];page.value=1;error.value='';load()}
async function load(){if(tab.value==='points')return;const v=++version;loading.value=true;error.value='';rows.value=[];try{const r=await rewardList(tab.value,{page:page.value,status:state.value});if(v!==version)return;rows.value=r.data.items;total.value=r.data.total||rows.value.length;drawEnabled.value=r.data.drawEnabled===true}catch(e){if(v===version)error.value=e.message||'加载失败'}finally{if(v===version)loading.value=false}}
async function edit(row){const v=++editVersion;editorType.value=tab.value;Object.keys(form).forEach(k=>delete form[k]);try{if(tab.value==='activities'){const all=[];let p=1,t=1;while(all.length<t&&p<=50){const r=await rewardList('goods',{page:p++});all.push(...r.data.items);t=r.data.total}if(all.length<t)throw new Error('商品超过 1000 件，请缩小奖品管理范围后配置');if(v!==editVersion)return;catalog.value=all;const r=row?(await rewardDetail(row.id)).data:null;if(v!==editVersion)return;Object.assign(form,r?{...r,prizes:r.prizes.map(p=>({goodsId:p.goodsId||0,weight:p.weight}))}:{title:'',cover:'',description:'',pointsCost:10,status:'DRAFT',startsAt:'',endsAt:'',prizes:[{goodsId:0,weight:1},{goodsId:all[0]?.id||0,weight:1}]})}else Object.assign(form,row?{...row,expectedStock:row.stock}:{title:'',kind:'BADGE',badgeCode:'',image:'',description:'',pointsCost:100,stock:100,status:'DRAFT'});dialog.value=true}catch(e){ElMessage.error(e.message)}}
function beforeUpload(file){if(uploading.value||saving.value)return false;if(!['image/png','image/jpeg'].includes(file.type)||file.size>5*1024*1024){ElMessage.warning('请选择 5MB 内的 PNG/JPG 图片');return false}return true}
async function upload(options){const v=editVersion;uploading.value=true;try{const r=await uploadReward(options.file);if(v===editVersion&&dialog.value)form[editorType.value==='goods'?'image':'cover']=r.data.url;options.onSuccess(r)}catch(e){options.onError(e);ElMessage.error(e.message)}finally{uploading.value=false}}
async function save(){if(saving.value||uploading.value)return;saving.value=true;const op=++mutationVersion,type=editorType.value,v=editVersion,data={...form,...(type==='activities'?{prizes:form.prizes.map(p=>({goodsId:p.goodsId||null,weight:p.weight}))}:{})};try{await saveReward(type,form.id,data);if(v===editVersion){dialog.value=false;ElMessage.success('保存成功');load()}}catch(e){if(op===mutationVersion)ElMessage.error(e.message||'保存失败')}finally{if(op===mutationVersion)saving.value=false}}
async function inspectPoints(){const token=getToken();points.value=null;try{const r=await readPoints(grantForm.memberId);if(token===getToken())points.value=r.data}catch(e){if(token===getToken())ElMessage.error(e.message)}}
async function grant(){
 if(saving.value)return;const op=++mutationVersion,token=getToken(),adminId=Number(userStore.id),v=version,storage=grantStorage(),snapshot=JSON.stringify({...grantForm});saving.value=true
 const current=()=>token===getToken()&&adminId===Number(userStore.id)&&v===version
 try{
  if(grantForm.note.trim().length<2)throw new Error('请填写免费发放原因')
  if(grantIntent&&grantIntent.snapshot!==snapshot)throw new Error('上次发放结果未确认，请保留原内容重试核对')
  const candidate=grantIntent||{adminId,snapshot,member:grantForm.memberId,data:{amount:grantForm.amount,note:grantForm.note,requestKey:crypto.randomUUID()}}
  await ElMessageBox.confirm('确认向玩家 '+candidate.member+' 免费发放 '+candidate.data.amount+' 积分？操作会写入账本和审计记录。','免费积分发放')
  if(!current())return
  grantIntent=candidate;localStorage.setItem(storage,JSON.stringify(candidate))
  await grantPoints(candidate.member,{...candidate.data})
  if(!current())return
  localStorage.removeItem(storage);grantIntent=null;ElMessage.success('积分已发放');await inspectPoints()
 }catch(e){if(!current())return;const code=[e.response?.data?.code,e.response?.status,e.code].map(Number).find(Number.isFinite);if(code>=400&&code<500&&code!==401&&code!==429){localStorage.removeItem(storage);grantIntent=null}if(e!=='cancel'&&e!=='close')ElMessage.error(e.message||'发放失败')}
 finally{if(op===mutationVersion)saving.value=false}
}
function fulfill(row){selected.value=row;Object.assign(shipping,{carrier:row.carrier,trackingNo:row.trackingNo});shippingDialog.value=true}
async function ship(){if(saving.value)return;saving.value=true;const op=++mutationVersion,id=selected.value.id,token=getToken(),v=version,data={...shipping};const current=()=>token===getToken()&&v===version&&selected.value?.id===id;try{await ElMessageBox.confirm('确认物流信息正确且实物已交承运方？','确认发货');if(!current())return;await shipReward(id,data);if(!current())return;shippingDialog.value=false;ElMessage.success('已记录发货');load()}catch(e){if(current()&&e!=='cancel'&&e!=='close')ElMessage.error(e.message||'发货失败')}finally{if(op===mutationVersion)saving.value=false}}
async function copyLink(id){try{await navigator.clipboard.writeText('/pages/rewards/activity?id='+id);ElMessage.success('小程序页面路径已复制')}catch{ElMessage.info('/pages/rewards/activity?id='+id)}}
</script>
<style scoped>.rewards-console{padding:28px 30px}.heading{display:flex;justify-content:space-between;align-items:center;margin-bottom:22px}.heading h1{font-size:26px;margin:0 0 8px}.heading p,.muted{color:#858995;font-size:12px}.toolbar{display:flex;align-items:center;gap:20px;margin:18px 0}.gap{margin:18px 0}.grant-form{max-width:640px;padding-top:20px}.prize-editor{display:flex;gap:6px;align-items:center;margin-bottom:8px}.live{color:#218b52}.el-pagination{justify-content:flex-end;margin-top:20px}.el-tabs{margin-top:18px}</style>
